-- A: (titulo do livro e nome do autor)SELECTl.titulo,a.nome AS autorFROM livro lINNER JOIN autor a ON l.id_autor = a.id_autor;-- B: (nome do aluno, titulo do livro e nome do autor)SELECTa.nome AS aluno,l.titulo AS livro,au.nome As autor,e.data_emprestimoFROM emprestimo eINNER JOIN aluno a ON e.id_aluno = a.id_alunoINNER JOIN emprestimoLivro el ON e.id_emprestimo = el.id_emprestimoINNER JOIN livro l ON el.id_livro = l.id_livroINNER JOIN autor au ON l.id_autor = au.id_autor;-- C: (livros com seus autores e, se tiver, alunos que o emprestaram)SELECTl.titulo AS livro,au.nome As autor,al.nome AS alunoFROM livro lINNER JOIN autor au ON l.id_autor = au.id_autorLEFT JOIN emprestimoLivro el ON l.id_livro = el.id_livroLEFT JOIN emprestimo e ON el.id_emprestimo = e.id_emprestimoLEFT JOIN aluno al ON e.id_aluno = al.id_aluno;/* Todo livro possui um autor, logo a correspondência é obrigatória (INNER)usando o (LEFT) posso retornar todos os livros, indpendentes se eles tem emprestimos cadsatrados ou não */-- D: (inversão da B com RIGHT)SELECTa.nome AS aluno,l.titulo AS livro,au.nome As autor,e.data_emprestimoFROM emprestimo eRIGHT JOIN aluno a ON e.id_aluno = a.id_alunoRIGHT JOIN emprestimoLivro el ON e.id_emprestimo = el.id_emprestimoRIGHT JOIN livro l ON el.id_livro = l.id_livroRIGHT JOIN autor au ON l.id_autor = au.id_autor;/* Mostra os livros e seus autores independente de possui aluno ou emprestimo vinculado a eles */-- E: (contar quantos emprestimos feitos por aluno de cada curso)SELECTal.curso,COUNT(e.id_emprestimo) AS total_emprestimosFROM aluno alLEFT JOIN emprestimo e ON al.id_aluno = e.id_emprestimoGROUP BY al.curso;